"use client"
import Image from "next/image"
import React, { useState } from "react"

const Wishlist = () => {
  const [wishlist, setWishlist] = useState(false)

  return (
    <div className="bg-white size-8 flex items-center justify-center rounded-full absolute top-3 right-3">
      <button className="size-6" onClick={() => setWishlist(!wishlist)}>
        <Image
          src={wishlist ? "/images/icon/heart-icon-fill.svg" : "/images/icon/heart-icon.svg"}
          width={1000}
          height={1000}
          alt="not found"
        />
      </button>
    </div>
  )
}

export default Wishlist
